;; K2b-0: a store built in ONE include build (bulk, like the desk), for comparison with
;; gen_store.clj (one commit per document).
;; Usage: bb scripts/bench/k2b_bulk_store.clj <new-project-dir> <dir-with-note-*.md> [n]
;; Takes the first n (default all) note-*.md of the second argument (generated by gen_store.clj),
;; declares the BenchNote model of gen_store.clj and runs `include build` in <new-project-dir>.
(require '[babashka.fs :as fs] '[babashka.process :as process] '[clojure.string :as str]
         '[kimun.cli.main :as main])
(let [[proj src n-str] *command-line-args*
      gs (slurp "scripts/bench/gen_store.clj")
      ;; the (def model {...}) form of gen_store.clj, read as data
      model (let [i (str/index-of gs "(def model")
                  r (java.io.PushbackReader. (java.io.StringReader. (subs gs i)))]
              (eval (nth (read {:read-cond :allow} r) 2)))
      files (sort (map str (fs/glob src "note-*.md")))
      files (if n-str (take (parse-long n-str) files) files)
      git! (fn [& a] (apply process/shell {:dir proj :out :string :err :string} "git" a))]
  (fs/create-dirs (fs/path proj "docs")) (fs/create-dirs (fs/path proj "models"))
  (doseq [f files] (fs/copy f (fs/path proj "docs" (fs/file-name f))))
  (spit (str (fs/path proj "models" "BenchNote.edn")) (pr-str model))
  (spit (str (fs/path proj "kimun.include.edn"))
        "{:include/version 1 :store {:path \".kimun\" :git :ignore} :models [\"models/*.edn\"] :documents [{:glob \"docs/**/*.md\" :model \"BenchNote\"}]}")
  (git! "init" "-q") (git! "config" "user.email" "t@e") (git! "config" "user.name" "t")
  (git! "add" "-A") (git! "commit" "-qm" "init")
  (let [t0 (System/nanoTime)
        r (:envelope (main/run ["include" "build"] {"USER" "bench"} proj))]
    (println "ok" (:ok r) "documents" (get-in r [:data :documents]) (format "seconds %.1f" (/ (- (System/nanoTime) t0) 1e9)))
    (when-not (:ok r) (println (pr-str r)))))
